INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-005/1-8', 'เงินไหลมา', 'Syngonium podophyllum', 'Schott.', 'ARACEAE', 'ไม้เลื้อย', 'ใบแยกเป็นแฉก รูปหัวใจ สีเขียว เลื้อยตามผนังโดยใช้ราก', 1, 2566);
