INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-008/1-4', 'ชบา', 'Hibiscus rosa-sinensis', 'L.', 'MALVACEAE', 'ไม้พุ่ม', 'ใบโตฐานใบกว้าง ขอบใบหยักฟันเลื่อย', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-009', 'ช้างน้าว', 'Ochna integerrima', '(Lour.) Merr.', 'OCHNACEAE', 'ไม้พุ่ม', 'ลำต้นมีหนาม ใบประกอบ ขนนกสองชั้น ดอกแบบซี่ร่มแยกแขนง', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-010/1-5', 'หัวใจม่วง', 'Tradescantia pallida', '(Rose) D.R.Hunt', 'COMMELINACEAE', 'ไม้ล้มลุก', 'ใบเดี่ยว สีม่วง เรียงสลับ ปลายใบแหลม ดอกสีม่วง กลีบดอก 3 กลีบทับซ้อนกัน', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-011', 'ถ้วยทอง', 'Solandra maxima', '(Moc. & Sessé ex Dunal) P.S.Green', 'SOLANACEAE', 'ไม้เลื้อย', 'ใบสลับ รี แผ่นใบมัน ดอกเดี่ยวออกที่ซอกใบ รูประฆังคว่ำ กลิ่นหอม', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-012/1-3', 'ปลงญี่ปุ่น', 'Cycas revoluta', 'Thumb.', 'CYCADACEAE', 'ไม้พุ่ม', 'ใบสีเขียวเข้มคล้ายใบมะพร้าว', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-013/1-3', 'เตยด่าง', 'Pandanus tectorius', 'Parkinson ex Du Roi', 'PANDANACEAE', 'ไม้พุ่ม', 'ใบเดี่ยว ออกจากลำต้น เวียนติดกันแน่น ขอบใบมีสีเขียว เรียวยาว', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-014/1-3', 'ประเดหวี', 'Dracaena fragrans', '(L.) Ker Gawl.', 'ASPARAGACEAE', 'ไม้พุ่ม', 'ใบแตกจากหน่อที่ปลายลำต้น สูง 5-10 ม. ลำต้นกลมจะไม่มีกิ่งก้านสาขา', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-015', 'ว่านหอยแครง', 'Tradescantia spathacea', 'Sw.', 'COMMELINACEAE', 'ไม้ลุ้มลุก', 'ใบเดี่ยว ออกเรียงซ้อนเป็นวงรอบ หลังใบสีเขียว ท้องใบสีม่วงแดง ใบหนา', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-016/1-2', 'เข็มญี่ปุ่น', 'Ixora chinensis', 'Lam.', 'RUBIACEAE', 'ไม้พุ่ม', 'ลำต้น 1-1.5 ซม.ลำต้นมีสีน้ำตาล ผิวรุขระ ดอกช่อซี่ร่ม กลีบดอกสีแดง', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-017/1-2', 'ทีทรี', 'Melaleuca alternifolia', '(Maiden & Betche) Cheel', 'MYRTACEAE', 'ไม้พุ่ม', 'ลำต้นสูง 1-2 เมตร ใบขนาดเล็ก เรียว แหลม ยอดลำต้นเป็นพุม แหลม', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-018/1-4', 'โมกบ้าน', 'Wrightia arborea', '(Dennst.) Mabb.', 'APOCYNACEAE', 'ไม้ต้น', 'ใบเดี่ยวออกเรียงตรงข้ามกันสลับตั้งฉาก แผ่นใบมีขนทั้งสองด้าน', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-019', 'กวักเงินกวักทอง', 'Aglaonema sp.1', '', 'ARACEAE', 'ไม้พุ่ม', 'ไม้พุ่ม สูง ประมาณ  15  เซนติเมตร ใบหนา มัน เรียบ ก้านใบสีชมพู', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-020', 'บัลลังเงิน', 'Aglaonema sp.2', '', 'ARACEAE', 'ไม้พุ่ม', 'สูง 20-30 ซม. ใบเดี่ยว  เส้นกลางใบขาว มีรอยสีขาว กระ จุด อยู่ทั่วใบ', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-021', 'แสงเงินแสงทอง', 'Aglaonema sp.3', '', 'ARACEAE', 'ไม้พุ่ม', 'สูง 20-30 ซม. ใบเดี่ยว  เรียงเวียน เส้นกลางใบและขอบใบสีชมพู', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-022/1-6', 'ราตรี', 'Cestrum nocturnum', 'L.', 'SOLANACEAE', 'ไม้พุ่ม', 'ลำต้นสูง 1-2 เมตร เปลือกเป็นสีเทาอ่อน ดอกช่อ สีขาว เล็ก ออกตามปลายใบ', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-023/1-5', 'ข่อย', 'Streblus asper', 'Lour.', 'MORACEAE', 'ไม้ต้น', 'ใบหนาหยาบ คล้ายกระดาษทราย เปลือกในมียางสีขาว', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-024/1-3', 'มะผู้มะเมีย', 'Cordyline fruticosa', '(L.) A.Chev.', 'ASPARAGACEAE', 'ไม้พุ่ม', 'ใบมีอย่างน้อย 2 สี แดง ม่วง', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-025/1-2', 'โมกบ้าน', 'Wrightia religiosa', '(Teijsm. & Binn.) Benth. ex Kurz', 'APOCYNACEAE', 'ไม้พุ่ม', 'ต้นสูง 5-10 ม. ใบประกอบขนนก ชั้นเดียว ดอกสีขาว ช่อดอกสั้นๆ', 1, 2566);
