INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-027/1-3', 'ไฮฮี', 'Ficus microcarpa', 'L.f.', 'MORACEAE', 'ไม้พุ่ม', 'ลำต้น สูง 1-2 เมตร แตกกิ่งก้านเป็นพุ่ม ใบเดียว ดอกสีม่วง อมน้ำเงิน รากอากาศ', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-028/1-2', 'ว่านหางจระเข้', 'Aloe vera', '(L.) Burm.f.', 'XANTHORRHOEACEAE', 'ไม้ล้มลุก', 'สูง 1 เมตร ลำต้นข้อปล้องสั้น ใบเดี่ยว อวบน้ำข้างในเป็นวุ้นใสสีเขียวอ่อน', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-029', 'ตะขบป่า', 'Flacourtia indica', 'indica (Burm.f.) Merr.', 'SALICACEAE', 'ไม้ต้น', 'เปลือกต้นมีหนามแหลม แข็ง ใบเดี่ยว ผลสุกสีแดงปนม่วง รสหวานปนฝาด', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-030/1-3', 'ทองอุไร', 'Tecoma stans', '(L.) Juss. ex Kunth', 'BIGNONIACEAE', 'ไม้พุ่ม', 'ใบเป็นใบประกอบแบบขนนก ปลายคี่ ดอกสีเหลือง กลีบเลี้ยงเป็นรูปถ้วย', 1, 2566);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-031', 'ทองกวาว', 'Butea monosperma', '(Lam.) Taub.', 'FABACEAE', 'ไม้พุ่ม', 'เปลือกต้นเป็นปุ่มปม สีน้ำตาลอ่อน ดอกออกเป็นช่อ ดอกสีแสด', 2, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-032', 'ลั่นทมขาว', 'Plumeria obtusa', 'L.', 'APOCYNACEAE', 'ไม้ต้น', 'สูง 5-10 เมตร ลำต้นสีเทา ตะปุ่มตะป่ำ กลีบดอก 5 กลีบ สีขาว ใบเดี่ยว รูปใบหอก', 2, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-033/1-5', 'ไทรย้อย', 'Ficus benjamina', 'L.', 'MORACEAE', 'ไม้ต้น', 'ลำต้นทรงพุ่มใหญ่ รากอากาศแทงย้อยรอบลำต้น', 2, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-034', 'พลับพลึง', 'Crinum asiaticum', 'L.', 'AMARYLLIDACEAE', 'ไม้พุ่ม', 'หัวใต้ดิน ลำต้นกลม ใบแตกหน่อซ้อนกัน ใบอวบน้ำ ดอกสีขาว', 2, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-035/1-2', 'จั๋งจีน', 'Rhapis humilis', 'Blume', 'ARECACEAE', 'ปาล์ม', 'ใบประกอบ เรียงสลับ รูปพัด แผ่เป็นครึ่งวงกลม', 2, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-036', 'จำปี', 'Magnolia x alba', '(DC.) Figlar', 'MAGNOLIACEAE', 'ไม้ต้น', 'ลำต้นสูง 10-20 ม. ดอกสีขาวนวล ใบเดี่ยว เรียงสลับรูปไข่', 2, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-037', 'ตะแบกน้ำ', 'Lagerstroemia floribunda', 'Jack', 'LYTHRACEAE', 'ไม้ต้น', 'ลำต้น สูง 10-25 ม. เรือนยอดแผ่กว้าง ดอกสีม่วงปนชมพู ออกเป็นช่อที่ปลายกิ่ง', 2, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-038/1-2', 'สาละลังกา', 'Couroupita guianensis', 'Aubl.', 'LECYTHIDACEAE', 'ไม้ต้น', 'ลำต้นสูง ใหญ่ เปลือลำต้นสีน้ำตาล แตกเป็นร่อง ผลกลมใหญ่ สีน้ำตาล ดอกดอกสีขมพูแกมแดง', 2, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-039', 'โพขี้นก', 'Ficus rumphii', 'Blume', 'MORACEAE', 'ไม้ต้น', 'ลำต้นสูง 10-20 เมตร  เรือนยอดแผ่กว้าง มีรากอากาศ  ใบเดี่ยวรูปหัวใจ', 2, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-040', 'เอื้องผึ้ง', 'Dendrobium lindleyi', 'Steud.', 'ORCHIDACEAE', 'ไม้รอเลื้อย', 'ใบเดี่ยว สีเขียว แผ่นใบแข็งหนาเหนียว ดอกสีเหลือง ช่อดอกเป็นช่อห้อย', 2, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-041/1-4', 'อโศกเซนคาเบรียล', 'Monoon longifolium', '(Sonn.) B.Xue & R.M.K.Saunders', 'ANNONACEAE', 'ไม้ต้น', 'ใบเรียวแหลม กิ่งและใบลู่ลง ทรงพุ่มรูปโดมสามเหลี่ยม', 2, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-042', 'แคขาว', 'Dolichandrone serrulata', '(Wall. ex DC.) Seem.', 'BIGNONIACEAE', 'ไม้ต้น', 'ลำต้น สูง 10-20 เมตร ดอกรูปแตรสีขาว ใบประกอบแบบขนนกชั้นเดียว', 2, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-043', 'ชมพู่น้ำดอกไม้', 'Syzygium jambos', '(L.) Alston', 'MYRTACEAE', 'ไม้ต้น', 'สูง5- 10 เมตร ใบเดี่ยว เรียงตรง กลีบดอกสีขาวหรือเหลืองอ่อน ผลสีเขียวอ่อน', 2, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-044', 'มะม่วง', 'Mangifera indica', 'L.', 'ANACARDIACEAE', 'ไม้ต้น', 'ใบเดี่ยวรูปหอก ปลายใบแหลม ผลดิบสีเขียว ผลสุกเหลือง เมล็ดเดี่ยวแข็ง', 3, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-045', 'แสงจันทร์', 'Pisonia grandis', 'R. Br.', 'NYCTAGINACEAE', 'ไม้ต้น', 'ใบเดียว ปลายใบแหลม ใบอ่อนสีเขียวอ่อน ลำต้นสีขาวเทา ลำต้นเรียบ', 3, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-046', 'ว่านหมื่นปี', 'Dieffenbachia seguine', '(Jacq.) Schott', 'ARACEAE', 'ไม้ล้มลุก', 'ใบใหญ่ เรียงสลับ กลางใบมีสีขาวกระจาย ก้านใบอวบ มีกาบ', 3, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-047', 'โปร่งกิ่ว', 'Dasymaschalon lomentaceum', 'Finet & Gagnep.', 'ANNONACEAE', 'ไม้พุ่ม', 'สูง 1-2 เมตร ใบเดี่ยว เรียงสลับ ดอกเดี่ยวสีขาว ออกที่ซอกใบใกล้ปลายกิ่ง', 3, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-048', 'เฟื่องฟ้า', 'Bougainvillea glabra', 'Choisy', 'NYCTAGINACEAE', 'ไม้พุ่ม', 'สูง 1-3 ม. ลำต้นสีน้ำตาล ขรุขระ มีหนาม ดอกชมพูเข้ม กลีบดอก 5 กลีบ ดอกช่อกระจุก', 3, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-049/1-4', 'ปาล์มสิบสองปันนา', 'Phoenix roebelenii', 'O''Brien', 'ARECACEAE', 'ปาล์ม', 'ต้นสูง 2 เมตร ก้านใบจัดเรียงระนาบเดี่ยว ช่อดอกสีเหลืองอ่อน', 4, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-050', 'แสยกใบเขียว', 'Euphorbia tithymaloides', 'L.', 'EUPHORBIACEAE', 'ไม้พุ่ม', 'ต้น สูง 1-3 ม. ลำต้นตั้งตรง ใบเดี่ยว กิ่งก้านเป็นสีเขียวมัน  ดอกช่อสีแดง', 4, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-051', 'เฟินใบมะขาม', 'Nephrolepis hirsutula', '(G.Forst.) C.Presl', 'POLYPODIACEAE', 'ไม้พุ่ม', 'ลำต้นเป็นเหง้าสั้น มีขนหรือเกล็ดสีน้ำตาล ใบย่อยรูปใบหอกแคบ สปอร์อยู่ใต้ใบ', 4, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-052/1-5', 'จันทร์แดง', 'Dracaena cochinchinensis', '(Lour.) S.C.Chen', 'ASPARAGACEAE', 'ไม้พุ่ม', 'สูง 1.5 - 2 ม. ใบเดี่ยว ออกเวียนสลับถี่ ๆ ที่ปลายยอด ปลายแหลม สีเขียวเข้ม', 4, 2567);
INSERT INTO plant (id_flower, local_name, scientific_name, scientific_surname, family, habit, characteristics, location_id, study_year) VALUES ('7-42000-001-053/1-2', 'กระบือเจ็ดตัว', 'Excoecaria cochinchinensis', 'Lour.', 'EUPHORBIACEAE', 'ไม้พุ่ม', 'ใบเดี่ยว เรียงสลับเวียนรอบกิ่ง หลังใบสีเขียว ท้องใบสีแดง ดอกช่อออกที่ปลายกิ่ง', 4, 2567);